/**
 * MongoDB-compatible ObjectId strings, built the way real ObjectIds are: a 4-byte timestamp, a
 * 5-byte random value fixed per process, and a 3-byte incrementing counter (24 hex chars).
 * Within one process they are therefore strictly increasing in creation order, so sorting or
 * paginating by `id` is reliable even for records created in the same millisecond (a timestamp
 * alone is not: two chat messages sent back-to-back can share it).
 *
 * IDs are generated by the data layer (never the UI), and the same strings are valid `ObjectId`s
 * when the repository is swapped for MongoDB.
 */
const hex = (bytes) => Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');

const processBytes = globalThis.crypto.getRandomValues(new Uint8Array(5));
let counter = globalThis.crypto.getRandomValues(new Uint32Array(1))[0] & 0xffffff;

export function newId() {
  const ts = Math.floor(Date.now() / 1000).toString(16).padStart(8, '0');
  counter = (counter + 1) & 0xffffff;
  return ts + hex(processBytes) + counter.toString(16).padStart(6, '0');
}

export const isId = (v) => typeof v === 'string' && /^[0-9a-f]{24}$/.test(v);
